INSERT INTO looks (id, name, icon, swatch, style, lighting, camera, avoid, cheap_model, good_model, resolution, voice, caption_style, music_mood, effect, builtin, sort_order) VALUES
  ('real', 'Real', 'camera', ARRAY['#1d2b3a','#c8a165','#e8e1d4']::text[], 'realistic live-action video, real people and places, natural skin texture, true-to-life colours, shallow depth of field', 'natural motivated light, soft contrast', 'steady locked-off camera at one fixed angle, 35mm lens look', NULL, 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'am_michael', 'minimal', 'pad', 'clean', true, 10),
  ('disney', 'Disney', 'castle', ARRAY['#3a6ea5','#f6d55c','#ed553b']::text[], 'classic hand-drawn 2D animated fairy-tale feature film, clean expressive linework, painterly watercolour backgrounds, charming expressive characters, fluid squash-and-stretch animation', 'warm storybook light, soft glow', 'steady locked-off camera at one fixed angle, medium shot', NULL, 'x-ai/grok-imagine-video-1.5-lite', 'google/veo-3.1-lite', '720p', 'af_heart', 'bold', 'pad', 'clean', true, 20),
  ('pixar', 'Pixar', 'box', ARRAY['#f5b942','#ff7a2f','#4aa3df']::text[], 'high-end 3D animated feature film, expressive stylised characters, soft subsurface skin, rich detailed textures, smooth appealing animation', 'soft cinematic golden light with gentle rim light', 'steady locked-off camera at one fixed angle, medium shot', NULL, 'x-ai/grok-imagine-video-1.5-lite', 'google/veo-3.1-lite', '720p', 'af_heart', 'bold', 'pad', 'clean', true, 30),
  ('anime', 'Anime', 'flower', ARRAY['#ff8fb1','#7ec8ff','#fff3b0']::text[], 'Japanese anime, hand-drawn cel shading, expressive eyes, detailed painted backgrounds, vivid colours', 'bright airy light with soft bloom', 'steady locked-off camera at one fixed angle, medium shot', NULL, 'x-ai/grok-imagine-video-1.5-lite', 'bytedance/seedance-2.0-mini', '720p', 'af_bella', 'box', 'pad', 'clean', true, 40),
  ('brainrot', 'Brain rot', 'laugh', ARRAY['#00e5ff','#ff2e93','#c6ff00']::text[], 'Italian brain rot internet-meme animation: glossy 3D render, every character is an absurd funny character made of a fruit, an animal or a bird (or a mix of them) with a big, very expressive face, eyes and mouth that show strong emotion, hyper-saturated colours, chaotic high-energy comedy', 'bright punchy light, strong colour pops', 'steady locked-off camera at one fixed angle, punchy close framing', NULL, 'x-ai/grok-imagine-video-1.5-lite', 'google/veo-3.1-fast', '720p', 'am_adam', 'bold', 'none', 'glitch', true, 50),
  ('gametrailer', 'Game', 'zap', ARRAY['#0b1f3a','#4da3ff','#ffb347']::text[], 'AAA fantasy-game launch trailer, pre-rendered CG, stylized semi-realistic characters with idealized faces, large luminous eyes, subsurface skin glow, individually simulated hair strands, real fabric weave, big particle and energy effects, volumetric god rays and floating dust, bloom, anamorphic lens, fast but readable action', 'low golden-hour backlight with sun flare or a cold storm key with lightning accents, deep contrast', 'steady locked-off camera at one fixed angle, wide heroic framing, a clear subject in every shot', 'collectible-figurine look, plastic skin, game HUD, on-screen text, 2D anime', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'am_michael', 'bold', 'epic', 'clean', true, 60),
  ('horror', 'Horror', 'surprised', ARRAY['#0a0f14','#7e8a96','#c1272d']::text[], 'cinematic supernatural horror, claustrophobic realism, psychological dread that builds slowly, realistic faces and frightened performances, restrained effects, the fear comes from anticipation, sound and scale rather than gore', 'cold desaturated light, flickering fluorescent or a single practical lamp, deep oppressive shadows', 'steady locked-off camera at one fixed angle, wide while things feel normal, a tighter frame on faces when fear arrives', 'gore, blood, cartoon monster, comedy, early monster reveal, bright cheerful colours, jump-cut morphing', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'am_onyx', 'minimal', 'suspense', 'clean', true, 70),
  ('fantasy', 'Fantasy', 'leaf', ARRAY['#2a1b4d','#ff9e7a','#7ad7ff']::text[], 'photorealistic fantasy film, gentle magical creatures and wonder, soft haze, glowing details, lived-in costumes, realistic motion and weight', 'dusk with a pink and orange sky reflected on water, soft magical glow, gentle mist, early stars', 'steady locked-off camera at one fixed angle, calm cinematic framing, shallow depth of field', 'cartoon look, over-saturated neon, plastic skin, extra limbs, text', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'af_heart', 'minimal', 'epic', 'clean', true, 80),
  ('retro35', 'Retro 35', 'film', ARRAY['#3b2a1d','#d9a066','#7a8f6a']::text[], 'a forgotten 1980s feature film shot on 35mm: visible film grain, soft halation, slightly faded colour, practical effects and miniatures, matte-painted backdrops, hand-built sets, slightly uneven vintage lens', 'hard practical light, warm tungsten against cool shadows, smoke and haze', 'steady locked-off camera at one fixed angle, classic 1980s framing, medium shot', 'digital sharpness, CGI sheen, modern colour grading, lens flares overdone, text', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'am_adam', 'bold', 'cinematic', 'clean', true, 90),
  ('painterly', 'Painterly', 'flower', ARRAY['#ff9ecb','#ffd166','#5ec4b6']::text[], 'painterly stylized 3D animation, brush-textured surfaces, warm storybook colours, expressive wordless comedy acting, readable silhouettes, charming exaggerated timing', 'soft warm key light with painted shadows', 'steady locked-off camera at one fixed angle, clear medium shot, every shot readable at a glance', 'photoreal skin, dark horror mood, text, extra characters', 'x-ai/grok-imagine-video-1.5-lite', 'google/veo-3.1-lite', '720p', 'af_bella', 'bold', 'funny', 'clean', true, 100),
  ('luxury', 'Luxury', 'gem', ARRAY['#1b1b1f','#e6d6a3','#c9a14a']::text[], 'premium commercial: macro product detail, glossy reflections, slow elegant motion, immaculate set design, real material textures (leather, glass, metal, silk), calm confident pacing', 'soft studio key with controlled highlights and a gold rim light, deep clean blacks', 'steady locked-off camera at one fixed angle, elegant beauty-shot framing with macro detail', 'clutter, text and logos, wobbling product shape, distorted hands, busy background', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'bm_george', 'minimal', 'chill', 'clean', true, 110),
  ('docu', 'Docu', 'video', ARRAY['#1c2a33','#9ad0ff','#d8c9a3']::text[], 'photoreal historical or nature documentary, natural light, true-to-life colour, observational camera, real locations and textures, calm authoritative feel', 'natural golden-hour or overcast daylight, no stylised colour', 'steady locked-off camera at one fixed angle, wide establishing frame or a detail close-up', 'fantasy elements, stylised colour grading, anachronisms, text overlays', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'bm_george', 'minimal', 'cinematic', 'clean', true, 120),
  ('securitycam', 'Cam', 'target', ARRAY['#10190f','#7fff7f','#b9c7b0']::text[], 'found-footage and security-camera clip: fixed high angle, low-resolution digital look, slight fisheye, compression grain, flat realistic light, ordinary people doing something unexpected', 'flat fluorescent or night-vision tone, no cinematic lighting', 'completely static camera at one fixed high angle, nothing in the frame moves but the people', 'cinematic grading, camera movement, on-screen timestamps or text, stylised effects', 'x-ai/grok-imagine-video-1.5-lite', 'google/veo-3.1-lite', '720p', 'am_michael', 'bold', 'none', 'clean', true, 130),
  ('estate', 'Tour', 'wind', ARRAY['#0f2a2e','#6fe3d1','#f1e3c6']::text[], 'hyper-realistic architectural walkthrough for luxury real estate: true materials (stone, timber, glass), clean staging, no people or very few, crisp detail', 'golden-hour sun through large windows, soft bounce light, glowing interior lamps', 'steady locked-off camera at one fixed angle, level horizon, wide architectural framing', 'warped walls, melting furniture, clutter, text, fisheye distortion', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'am_michael', 'minimal', 'chill', 'clean', true, 140),
  ('toon3d', 'Toon 3D', 'heart', ARRAY['#ff9ad5','#ffe066','#66d9ff']::text[], 'bright cheerful 3D cartoon for children: rounded friendly characters, big simple shapes, saturated candy colours, bouncy squash-and-stretch, a magical colourful world', 'bright even daylight, soft shadows, sparkles', 'steady locked-off camera at one fixed angle, clear friendly medium shot', 'scary or dark mood, realistic skin, text, tiny details', 'x-ai/grok-imagine-video-1.5-lite', 'google/veo-3.1-lite', '720p', 'af_nicole', 'bold', 'upbeat', 'clean', true, 150),
  ('indie', 'Indie', 'coffee', ARRAY['#2b2118','#d9b38c','#6f8ea6']::text[], 'quiet naturalistic indie drama: real faces and small gestures, lived-in rooms, restrained performances, silence and pauses carry the feeling', 'available light, a practical lamp at night, soft window light, natural contrast', 'steady locked-off camera at one fixed angle, intimate medium close-up, shallow depth of field', 'glamour lighting, over-acted emotion, fast cuts, text', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'af_heart', 'minimal', 'chill', 'clean', true, 160),
  ('action', 'Action', 'flame', ARRAY['#2a0f0a','#ff7a3d','#3dc7ff']::text[], 'kinetic live-action fight and chase choreography, clear readable cause and effect, grounded physics, sweat, dust and impact, one hero and one opponent clearly told apart', 'hard practical light, strong contrast, colour contrast between the two sides', 'steady locked-off camera at one fixed angle, wide enough to read the geography of the fight', 'gore, confusing cuts, duplicated fighters, rubbery limbs, text', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'am_adam', 'bold', 'epic', 'clean', true, 170),
  ('inkpaint', 'Ink', 'pen', ARRAY['#16122b','#b3a8ff','#ff6f91']::text[], 'graphic painted 2.5D animation, ink-wash and brush strokes, flat layered cut-out depth, bold colour accents on a muted ground, expressive hand-made transformations', 'painted flat light with strong colour accents', 'steady locked-off camera at one fixed angle, flat layered composition', 'photorealism, 3D plastic look, text', 'x-ai/grok-imagine-video-1.5-lite', 'bytedance/seedance-2.0-mini', '720p', 'af_bella', 'minimal', 'chill', 'clean', true, 180),
  ('epicfilm', 'Epic', 'clapper', ARRAY['#141414','#f2f2f2','#d4a84b']::text[], 'ultra-realistic cinematic motivational short film: an emotional human story told in a few strong images, honest faces, weather and landscape as feeling, scale and silence', 'dramatic motivated light, golden hour or blue hour, soft rim light on faces', 'steady locked-off camera at one fixed angle, wide landscape frame or a close-up on a face', 'stock-footage look, text, over-saturation, extra people', 'google/veo-3.1-lite', 'google/veo-3.1-fast', '720p', 'am_michael', 'bold', 'cinematic', 'clean', true, 190)
